<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Pengguna; use App\Models\LogLogin; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function login(Request $r){$d=$r->validate(['username'=>'required|string|max:100','password'=>'required|string|max:255','device_name'=>'required|string|max:100']);$u=Pengguna::where('username',$d['username'])->first();$ok=$u && $u->is_aktif && Hash::check($d['password'],$u->password_hash);LogLogin::create(['id_pengguna'=>$u?->id_pengguna,'username_dicoba'=>$d['username'],'berhasil'=>(bool)$ok,'ip_address'=>$r->ip(),'user_agent'=>substr((string)$r->userAgent(),0,255),'waktu'=>now()]);if(!$ok)return response()->json(['message'=>'Kredensial tidak valid'],422);$u->forceFill(['terakhir_login'=>now()])->save();return response()->json(['token'=>$u->createToken($d['device_name'])->plainTextToken,'user'=>['id_pengguna'=>$u->id_pengguna,'username'=>$u->username,'role'=>$u->role?->nama_role]]);} public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Logout berhasil']);} }
